17	/**
18	 * Create a booking and authorise the block-price hold (mock payments). Flow:
19	 * validate → create booking (pending) → payments.authorizeHold → confirm
20	 * booking with the payment ref. Capture happens at session end (M6).
21	 */
22	export async function createBooking(
23	  input: BookingCreateInput,
24	): Promise<BookingResult> {
25	  const profile = await requireRole("customer");
26	  if (profile.is_suspended) {
27	    return { error: t("booking.suspended") };
28	  }
29	
30	  const parsed = bookingCreateSchema.safeParse(input);
31	  if (!parsed.success) {
32	    const fieldErrors: Record<string, string> = {};
33	    for (const issue of parsed.error.issues) {
34	      const key = String(issue.path[0] ?? "");
35	      if (key && !fieldErrors[key]) fieldErrors[key] = issue.message;
36	    }
37	    return { error: "Please check your booking details.", fieldErrors };
38	  }
39	  const d = parsed.data;
40	
41	  const provider = await getApprovedProvider(d.providerId);
42	  if (!provider) return { error: "This listener isn't available right now." };
43	
44	  const priceBlockCents = priceForBlock(provider, d.blockMinutes);
45	  const supabase = await createClient();
46	
47	  const { data: booking, error: insErr } = await supabase
48	    .from("bookings")
49	    .insert({
50	      customer_id: profile.id,
51	      provider_id: provider.id,
52	      slot_id: d.slotId ?? null,
53	      block_minutes: d.blockMinutes,
54	      start_mode: d.startMode,
55	      scheduled_at: d.scheduledAt ?? null,
56	      price_block_cents: priceBlockCents,
57	      overage_per_min_cents: provider.overage_per_min_cents,
58	      status: "pending",
59	    })
60	    .select("id")
61	    .single();
62	
63	  if (insErr || !booking) {
64	    return { error: "We couldn't start your booking. Please try again." };
65	  }
66	
67	  const payments = getPayments();
68	  const { customerRef } = await payments.ensureCustomer(profile.id);
69	  const hold = await payments.authorizeHold({
70	    bookingId: booking.id,
71	    amountCents: priceBlockCents,
72	    customerRef,
73	  });
74	
75	  const { error: updErr } = await supabase
76	    .from("bookings")
77	    .update({ status: "confirmed", payment_ref: hold.paymentRef })
78	    .eq("id", booking.id);
79	
80	  if (updErr) {
81	    return { error: "We couldn't confirm your booking. Please try again." };
82	  }
83	
84	  redirect(`/account?booked=${booking.id}`);
85	}
