16	export function ProviderSessionFlow({
17	  bookingId,
18	  blockMinutes,
19	  alreadyInProgress,
20	}: {
21	  bookingId: string;
22	  blockMinutes: number;
23	  alreadyInProgress: boolean;
24	}) {
25	  const router = useRouter();
26	  const [phase, setPhase] = React.useState<"incoming" | "incall">(
27	    alreadyInProgress ? "incall" : "incoming",
28	  );
29	  const [busy, setBusy] = React.useState(false);
30	  const [error, setError] = React.useState<string | null>(null);
31	
32	  async function accept() {
33	    setBusy(true);
34	    setError(null);
35	    const res = await startSession(bookingId);
36	    if (res.error) {
37	      setError(res.error);
38	      setBusy(false);
39	      return;
40	    }
41	    setPhase("incall");
42	  }
43	
44	  if (phase === "incall") {
45	    return (
46	      <CallStage
47	        name={GUEST}
48	        avatarColor={GUEST_COLOR}
49	        endLabel={t("session.endForSafety")}
50	        onEnd={async (elapsed) => {
51	          await endSession(bookingId, elapsed);
